      "path": "src/host.ts",
      "content": "import type { IncomingMessage, ServerResponse } from 'node:http'\nimport { createRequire } from 'node:module'\nimport type { Context } from '@deepseek-ai/cordis'\nimport Schema from '@deepseek-ai/schemastery'\nimport { createApiDispatcher, type RequestTrustCheck } from './core/host-api.js'\nimport type { OperationChannel } from './core/external-journal.js'\nimport { bindLoaderHost, type LoaderHost } from './core/live-plugin.js'\nimport { createRegistryController, type RegistrySettingsStore } from './core/registry-controller.js'\nimport { wireRegistrySettings, unwrapConfig } from './core/settings-compat.js'\nimport { resolveActiveProfile } from './core/active-profile.js'\nimport { registerTools } from './tools.js'\nimport { appExitFromContext, scheduleRestart } from './core/restart.js'\nimport type { PluginManagerLike } from './core/toggle.js'\n\nconst require = createRequire(import.meta.url)\nconst pkg = require('../package.json') as { name: string; version: string }\n\nexport const name = 'dshm'\n\n// dshm_* 八个工具（src/tools.ts）\nexport const inject: string[] = ['tools']\n\nexport interface Config {\n  registryUrl?: string\n  timeoutMs?: number\n  cacheTtlMin?: number\n  communityCatalog?: boolean\n  communityCatalogPin?: string\n  /** issue #57 / ADR-0035：会话工具开关（undefined = 开） */\n  sessionTools?: boolean\n  /** issue #57 / ADR-0035：提示词段开关（undefined = 开；tools off 时级联强制不注入） */\n  sessionPrompt?: boolean\n}\n\n/**\n * 0.1.7+ 的 DSH schemastery 才有 `.volatile()`（标记字段进自动生成设置页 + loader 原地提交）；\n * 旧版（≤0.1.5，schemastery 3.18.2）缺方法时保持普通字段——旧 settings API 的 scope 自带 live 语义。\n * `volatile()` 幂等性：重复包裹会 throw，这里每字段只调一次。\n */\nfunction live<T>(field: Schema<T>): Schema<T> {\n  const volatile = (field as unknown as { volatile?: () => Schema<T> }).volatile\n  return typeof volatile === 'function' ? volatile.call(field) : field\n}\n\nexport const Config: Schema<Config> = Schema.object({\n  registryUrl: live(Schema.string().description('registry 地址：空值使用默认官方清单；支持 HTTPS URL、loopback HTTP URL 或本机绝对路径/file://（整体覆盖默认清单，live 生效）')),\n  timeoutMs: live(Schema.number().default(20000).description('上游请求超时（毫秒）')),\n  cacheTtlMin: live(Schema.number().default(60).description('registry 缓存时长（分钟）')),\n  communityCatalog: live(Schema.boolean().default(true).description('社区清单：awesome-dsh-plugin 全量社区目录叠加进市场（只读，live 生效）')),\n  communityCatalogPin: live(Schema.string().description('社区目录版本锁定：精确 semver（如 2026.928.1），空值跟随 latest')),\n  sessionTools: live(Schema.boolean().default(true).description('会话工具：关闭后新会话不再提供 dshm_* 工具，已打开的对话从下一次回复起也不能再调用；市场页面与 dshm 命令行不受影响')),\n  sessionPrompt: live(Schema.boolean().default(true).description('系统提示词引导：关闭后新会话不再注入 dshm 用法段，工具仅在显式要求时使用；会话工具关闭时本项不生效')),\n})\n\nexport function apply(ctx: Context, config: Config): void {\n  // 卸载前的 live-disable 依赖 loader（skillhub 同款）\n  bindLoaderHost(ctx as unknown as LoaderHost)\n\n  // 0.9.0 双 profile（ADR-0005）：宿主当前 profile 单一事实源——apply 期解析一次，\n  // host 生命周期内不可变；GUI/工具/HTTP/缓存分段全部消费同一对象。\n  const profile = resolveActiveProfile(ctx)\n  ctx.logger?.info?.('dsh-m: active profile %s (dir=%s, source=%s)', profile.name, profile.dir, profile.source)\n\n  // registry controller：active config / configured / pending / rejected 分离 + generation fence；\n  // tools 与 Host API 共用同一 active config object（apply 原地更新字段，live 生效）。\n  // unwrapConfig：0.1.7 上 volatile 字段是 cosmokit Volatile 引用，先解包成 plain 值再进 controller。\n  const controller = createRegistryController(unwrapConfig(config), { profile: profile.name })\n  // DSH 0.1.2-rc.1 / 0.1.5-rc.1 / 0.1.7-rc.1 / 0.1.7-rc.2 都经 dsh-cmdline 暴露 appExit；\n  // using it avoids guessing the service unit from release-specific cgroups.\n  const appExit = appExitFromContext(ctx)\n  const restart = (port: number | null = null, channel?: OperationChannel) => scheduleRestart(port, { appExit, channel })\n\n  // 开关委派的官方服务探测（ADR-0001）：运行时按服务存在性探测，不判 DSH 版本号。\n  // 0.9.8 与 dsh-market 同源修正（Windows 实机 2026-10-01）：pluginManager 是惰性服务，\n  // 外层 apply ctx 的一次性 get 在本机探不到；改为双上下文探测（webServer 注入回调的\n  // hostCtx 优先——dshmarket 即此路径，两轮覆盖安装实证）+ inject 惰性拉起兜底。\n  let serviceCtx: unknown = undefined\n  const getService = (): PluginManagerLike | undefined => {\n    for (const c of [serviceCtx, ctx]) {\n      const svc = (c as unknown as { get?: (name: string) => unknown } | null)?.get?.('pluginManager') as\n        | PluginManagerLike\n        | undefined\n      if (svc !== undefined && svc !== null) return svc\n    }\n    return undefined\n  }\n  // 惰性拉起：get 缺席时经 cordis inject 等官方服务实例化（短超时，仍缺席由调用方 fail-closed）\n  const ensureService = (timeoutMs = 5_000): Promise<PluginManagerLike | undefined> =>\n    new Promise((resolve) => {\n      const immediate = getService()\n      if (immediate !== undefined) {\n        resolve(immediate)\n        return\n      }\n      let settled = false\n      const finish = () => {\n        if (settled) return\n        settled = true\n        clearTimeout(timer)\n        resolve(getService())\n      }\n      const timer = setTimeout(finish, timeoutMs)\n      try {\n        ;(ctx as unknown as { inject?: (deps: string[], cb: (c: unknown) => void) => unknown }).inject?.(['pluginManager'], () => finish())\n      } catch {\n        finish()\n      }\n    })\n  registerTools(ctx, controller.config, { restart, getService, ensureService }, profile)\n\n  // 设置页接线（双代兼容，详见 core/settings-compat.ts）：\n  // - ≤0.1.5：settings.register('dshm', …) scope（get/update/watch）；\n  // - 0.1.7-rc.1 / rc.2：Config `.volatile()` 字段自动生成设置页（autoGenerate 默认开，无需 configure），\n  //   读 = loader 解析的 Config 引用，写 = settings.update(ns, patch)，通知 = loader/volatile-update；\n  // - 其他形态：降级 cordis 配置文件通路。任何失败只 warn，不拖垮 webServer / tools。\n  ctx.inject(['settings'], (c) => {\n    const settings = (\n      c as unknown as { settings?: unknown }\n    ).settings\n    try {\n      const outcome = wireRegistrySettings({\n        ctx,\n        settings,\n        schema: Config,\n        parsedConfig: config,\n        packageName: pkg.name,\n        logger: ctx.logger,\n        attachStore: (store: RegistrySettingsStore) => controller.attachStore(store),\n      })\n      if (outcome === 'legacy' || outcome === 'forms') {\n        ctx.logger?.debug?.('dsh-m: settings store attached (%s)', outcome)\n      }\n    } catch (err) {\n      ctx.logger?.warn?.('dsh-m: settings 集成失败，registry 地址走 cordis 配置文件')\n      ctx.logger?.warn?.(err)\n    }\n  })\n\n  // 本地 API：单路由 + method 分发（信任检查与状态映射在 core/host-api.ts）。\n  // 0.9.0（ADR-0005）：入口信任检查全量委派官方 connection.requestRejection——\n  // Desktop 桥剥 Origin 的请求按官方语义（trustedHosts/loopback/cross-site/Origin:null）判定，\n  // 服务缺席或抛错一律 fail-closed 403（warn 一次）。\n  ctx.inject(['webServer'], (c) => {\n    const server = (\n      c as unknown as {\n        webServer: {\n          register: (route: {\n            kind: string\n            path: string\n            handler: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>\n          }) => void\n        }\n      }\n    ).webServer\n    serviceCtx = c // 0.9.8：webServer 注入回调的 hostCtx 是 pluginManager 的可见上下文（dsh-market 同款）\n    const rejectRequest = createRequestRejection(ctx)\n    const handleApi = createApiDispatcher({\n      controller,\n      pkg,\n      profile,\n      deps: {\n        scheduleRestart: restart,\n        getService,\n        ensureService,\n        rejectRequest,\n      },\n    })\n    server.register({\n      kind: 'exact',\n      path: '/dshm',\n      handler: (req, res) => {\n        void handleApi(req, res)\n      },\n    })\n  })\n}\n\n/** 守卫式官方 requestRejection 委派：缺席/抛错 fail-closed 403（warn 一次，不刷日志）。 */\nfunction createRequestRejection(ctx: Context): RequestTrustCheck {\n  let warned = false\n  const warnOnce = (err: unknown) => {\n    if (warned) return\n    warned = true\n    ctx.logger?.warn?.('dsh-m: 官方 connection.requestRejection 不可用，/dshm 全入口 fail-closed 403（ADR-0005）')\n    if (err) ctx.logger?.warn?.(err)\n  }\n  return (req) => {\n    try {\n      const connection = (ctx as unknown as { get?: (name: string) => unknown }).get?.('connection') as\n        | { requestRejection?: (r: { headers: IncomingMessage['headers'] }) => 401 | 403 | undefined }\n        | undefined\n      const reject = connection?.requestRejection\n      if (typeof reject !== 'function') {\n        warnOnce(undefined)\n        return 403\n      }\n      return reject.call(connection, { headers: req.headers }) ?? undefined\n    } catch (err) {\n      warnOnce(err)\n      return 403\n    }\n  }\n}\n"
    },
    {
      "path": "src/tools.ts",
      "content": "/**\n * dshm_* agent 工具（DESIGN.md §5）：7 个 defineTool + systemPrompt 注入。\n * 渲染文本遵循 skillhub 的 agent 体验约束：卡片已展示、对用户最多一句、不打印命令。\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\n\n/**\n * dsh-tools 0.2.2-rc.1 运行时 register 支持 (definition, options)（lib/index.js :433，options.when\n * 步时激活 + 装配期可见性过滤 :533/:551），类型声明滞后为单参（types/index.d.ts:636）——\n * issue #57 / ADR-0035 会话开关经 when 谓词门控，此处按运行时契约窄化类型。\n * 8 个 dshm_* 工具全部经此注册（自验：grep -c '^  registerGated(ctx, defineTool' 恰 8——行首锚定后定义行与注释行天然不匹配）。\n */\nfunction registerGated(ctx: Context, definition: ReturnType<typeof defineTool>, when: () => boolean): void {\n  ;(ctx.tools.register as unknown as (d: ReturnType<typeof defineTool>, o: { when: () => boolean }) => void).call(ctx.tools, definition, { when })\n}\nimport { installTimeoutMs } from './core/env.js'\nimport { SESSION_PROMPT_SECTION_NAME, SESSION_PROMPT_SECTION_ORDER, resolveSessionPromptText, sessionToolsEnabled } from './core/session-gate.js'\nimport {\n  listInstalledWithMeta,\n  listMarket,\n  type InstalledResult,\n} from './core/market.js'\nimport {\n  installFromRegistry,\n  uninstallPlugin,\n  upgradePlugin,\n  InstallGuardError,\n} from './core/market-mutation.js'\nimport type { CommunityRegistrySummary } from './core/merged-market.js'\nimport type { RegistryConfig, RegistryEntry, RegistryState } from './core/registry.js'\nimport { COMMUNITY_CATEGORY_LABELS } from './core/community.js'\nimport { parseMarketQueryInput, PRIMARY_CATEGORY_LABELS, SEARCH_CORE_DEADLINE_MS, INSTALLED_CORE_DEADLINE_MS } from './core/market-query.js'\nimport { publishedAtParts } from './core/published-at.js'\nimport { unsupportedCauseLabel } from './core/upgrade-target.js'\nimport { appExitFromContext, scheduleRestart, type RestartResult } from './core/restart.js'\nimport { readLastRestart, foldLastRestartIntoJournal, type LastRestartState } from './core/restart-state.js'\nimport type { OperationChannel } from './core/external-journal.js'\nimport { togglePlugin as coreTogglePlugin, type ToggleResult } from './core/toggle.js'\nimport { resolveActiveProfile, assertWriteAllowed, type ActiveProfile } from './core/active-profile.js'\nimport { desktopInstallFromRegistry, desktopToggle, desktopUninstall, desktopUpgradeFromRegistry } from './core/profile-ops.js'\nimport { routeWebMutation } from './core/exec-route.js'\n\n/** 分类中文标签（0.7.0 Task 5）：精选 5 类（单一事实源 market-query PRIMARY_CATEGORY_LABELS）+ 社区已知标签（单一事实源 COMMUNITY_CATEGORY_LABELS）；未知 slug 原样。 */\nfunction categoryLabelOf(category: string): string {\n  return PRIMARY_CATEGORY_LABELS[category] ?? COMMUNITY_CATEGORY_LABELS[category] ?? category\n}\n\n/** 工具 deadline 对齐（M1 Task 7）：search 45s（core 44s）、list/outdated 65s（core 60s + 5s 回包余量）。\n *  core 侧两个 deadline 常量单源于 market-query（0.9.92，与 CLI 共用）；TOOL_TIMEOUT 为本端信封专属。 */\nconst SEARCH_TOOL_TIMEOUT_MS = 45_000\nconst INSTALLED_TOOL_TIMEOUT_MS = 65_000\n\n/** 社区 summary 四键投影（Task 7 ②）：agent 工具输出只带这四个字段。 */\nexport function communityToolSummary(c: CommunityRegistrySummary | null | undefined): {\n  acceptedCount: number | null\n  route: string | null\n  status: string\n  version: string | null\n} {\n  if (!c) return { acceptedCount: null, route: null, status: 'unavailable', version: null }\n  const unavailableLike = c.status === 'disabled' || c.status === 'unavailable'\n  return {\n    acceptedCount: unavailableLike ? null : c.acceptedCount,\n    route: unavailableLike ? null : c.route,\n    status: c.status,\n    version: c.version,\n  }\n}\n\n/** latestErrorCode → 安全化原因（Task 7 ⑨）：不泄露内部细节，按 code 归类。 */\nexport function latestErrorCodeReason(code: string | null | undefined): string {\n  switch (code) {\n    case 'budget-exhausted':\n      return '因 GitHub 预算未完成'\n    case 'rate-limited':\n      return 'GitHub 限流'\n    case 'timeout':\n      return '检查超时'\n    default:\n      return '网络错误'\n  }\n}\n\n/** 可注入 market 依赖（测试用；生产走真实 core）。 */\nexport interface ToolMarketDeps {\n  listMarket?: typeof listMarket\n  listInstalledWithMeta?: typeof listInstalledWithMeta\n  installFromRegistry?: typeof installFromRegistry\n  uninstallPlugin?: typeof uninstallPlugin\n  upgradePlugin?: typeof upgradePlugin\n  restart?: (port: number | null, channel?: OperationChannel) => RestartResult\n  togglePlugin?: typeof coreTogglePlugin\n  /** 0.9.0：Desktop adapter 注入（测试可替换；生产 = profile-ops 实现） */\n  desktopInstall?: typeof desktopInstallFromRegistry\n  desktopToggle?: typeof desktopToggle\n  /** 0.9.8：Desktop 卸载/升级委派（dsh-market 同策略；生产 = profile-ops 实现） */\n  desktopUninstall?: typeof desktopUninstall\n  desktopUpgrade?: typeof desktopUpgradeFromRegistry\n  /** 0.9.8：官方服务探测/惰性拉起（host.ts 共用同一解析器；缺省退回外层 ctx 一次性 get） */\n  getService?: () => unknown\n  ensureService?: (timeoutMs?: number) => Promise<unknown>\n  /** ADR-0034（issue #65）：web 执行能力门（测试注入缝；生产 = exec-route 实现） */\n  routeWebMutation?: typeof routeWebMutation\n}\n\nfunction cloneJson(value: unknown) {\n  return JSON.parse(JSON.stringify(value))\n}\n\nfunction summaryOf(state: RegistryState): { isDefault: boolean; status: string; stale: boolean } {\n  return { isDefault: state.isDefault, status: state.status, stale: state.stale }\n}\n\n/** 注册表状态一行（内部信息，供 agent 判断市场数据是否新鲜；retro 2026-11-01 第 7 项）。 */\nfunction registryNoteOf(state: RegistryState): string {\n  const parts: string[] = [`${state.source ?? 'unknown'}`]\n  if (typeof state.count === 'number') parts.push(`${state.count} 条`)\n  if (state.fetchedAt) parts.push(`抓取于 ${state.fetchedAt}`)\n  if (state.stale) parts.push('过期缓存')\n  if (state.status !== 'ready') parts.push(`状态 ${state.status}`)\n  if (Array.isArray(state.errors) && state.errors.length > 0) parts.push(`错误 ${state.errors.length} 条`)\n  return parts.join(' · ')\n}\n\n/** 上次重启终态尾行（#51/ADR-0032）：状态文件缺失 → 空串（输出零变化）；assumed 不显耗时（R2-2）。 */\nfunction lastRestartTail(last?: LastRestartState): string {\n  if (!last) return ''\n  const body = last.ok\n    ? (last.assumed ? '成功（假定，无端口可探）' : `成功（${(last.elapsedMs / 1000).toFixed(1)}s）`)\n    : `失败（${last.reason ?? '未知原因'}）`\n  return `\\n上次重启终态：${body}`\n}\n\nexport function registerTools(\n  ctx: Context,\n  cfg: RegistryConfig,\n  deps: ToolMarketDeps = {},\n  profile: ActiveProfile = resolveActiveProfile(ctx),\n): void {\n  const m = {\n    listMarket: deps.listMarket ?? listMarket,\n    listInstalledWithMeta: deps.listInstalledWithMeta ?? listInstalledWithMeta,\n    installFromRegistry: deps.installFromRegistry ?? installFromRegistry,\n    uninstallPlugin: deps.uninstallPlugin ?? uninstallPlugin,\n    upgradePlugin: deps.upgradePlugin ?? upgradePlugin,\n    desktopInstall: deps.desktopInstall ?? desktopInstallFromRegistry,\n    desktopToggle: deps.desktopToggle ?? desktopToggle,\n    desktopUninstall: deps.desktopUninstall ?? desktopUninstall,\n    desktopUpgrade: deps.desktopUpgrade ?? desktopUpgradeFromRegistry,\n  }\n  const restart = deps.restart ?? ((port: number | null = null, channel?: OperationChannel) =>\n    scheduleRestart(port, { appExit: appExitFromContext(ctx), channel }))\n  const toggle = deps.togglePlugin ?? coreTogglePlugin\n  // 开关委派服务探测（ADR-0001）：运行时按存在性，不判版本号。\n  // 0.9.8：host.ts 共用解析器（双上下文 + 惰性拉起）优先；缺省退回外层 ctx 一次性 get（旧行为）。\n  const getService = deps.getService ?? ((): unknown =>\n    (ctx as unknown as { get?: (name: string) => unknown }).get?.('pluginManager'))\n  const ensureService = deps.ensureService\n  const routeGate = deps.routeWebMutation ?? routeWebMutation\n\n  registerGated(ctx, defineTool({\n    name: 'dshm_search',\n    description:\n      'Search the DSH plugin marketplace (dsh-m) and show clickable plugin cards. ALWAYS call this instead of web_search or bash when the user wants to find/recommend/browse DSH plugins (插件). Call EXACTLY ONCE per user message; extract a real keyword (主题, 搜索) rather than pasting the whole sentence. Dual catalog: ~23 hand-curated 精选 entries plus a 6,000+ community catalog — default searches all; pass source=\"community\" or \"primary\" to zone in. Returns 10 cards by default; use offset (take nextOffset from the result) for more batches. Cards may carry audience=\"internal\" (作者自用; do not proactively recommend to general users unless the user names one or asks about internal rollout) and decoupled=true (版本无关, survives DSH upgrades without per-release adaptation). After cards appear, reply with AT MOST one short sentence. Do not print install commands.',\n    parameters: {\n      query: { type: 'string', description: 'Main keyword, e.g. 主题 or 搜索. Optional; omit to browse.' },\n      category: {\n        type: 'string',\n        description: `Optional category: curated ${Object.keys(PRIMARY_CATEGORY_LABELS).join('/')} or any community slug ([a-z0-9-]{1,32}, e.g. theme/memory/git).`,\n      },\n      source: {\n        type: 'string',\n        description: 'Zone filter: \"community\" (6,000+ community catalog), \"primary\" (hand-curated 精选), or \"all\" (default).',\n      },\n      limit: { type: 'number', description: 'Cards in this batch. Default 10, clamp 1-80.' },\n      offset: { type: 'number', description: 'Pagination offset (0-based). Pass nextOffset from the previous result to fetch the next batch.' },\n    },\n    output: {\n      schema: { type: 'object', additionalProperties: true },\n      render: (_args, value) => [{ type: 'text', text: renderSearch(value as SearchOut) }],\n      presentationMeta: (_args, value) => ({ kind: 'dshm-search', ...(value as object) }),\n    },\n    presentCall: (args) => ({\n      card: 'generic',\n      title: `DSH 市场 · ${String(args.query || args.category || (args.source && args.source !== 'all' ? args.source : '') || '浏览')}`,\n      kind: 'search',\n      content: [],\n    }),\n    presentResult: (_args, { isError, meta }) => ({\n      card: 'generic',\n      title: isError ? '市场搜索失败' : `DSH 市场 · ${(meta as SearchOut | undefined)?.items?.length ?? 0} 条`,\n      content: [],\n    }),\n    timeoutMs: SEARCH_TOOL_TIMEOUT_MS,\n    async execute(args, exec) {\n      // 0.9.92 三端查询文法：category/source/limit/offset 经 market-query 单一入口归一\n      //（与 host-api/CLI 同源同语义；文法违规 throw 直飞，与此前 throw new Error 同通道）。\n      // 分区参数语义 0.7.0 Task 5 不变；primary_only 已删除（D6a 允许破坏性变更）。\n      const intake = parseMarketQueryInput(\n        { category: args.category, source: args.source, limit: args.limit, offset: args.offset },\n        { limitMax: 80, limitDefault: 10 },\n      )\n      const { category, source, offset, limit } = intake\n      // metadata-only：agent 卡片不需要 latest；发布时刻 opt-in 恒开（ADR-0031，B5——维护信号进卡片行）；\n      // 与 Host GUI 共用 host namespace；deadline 44s 是本 waiter 的绝对上限（工具 timeout 45s 先到兜底）\n      const result = await m.listMarket(cfg, {\n        query: String(args.query || ''),\n        category,\n        source,\n        offset,\n        limit,\n        withLatest: false,\n        withPublishedAt: true,\n        namespace: 'host',\n        deadlineMs: SEARCH_CORE_DEADLINE_MS,\n        signal: exec?.signal,\n        profileDir: profile.dir,\n        profile: profile.name,\n      })\n      // 安装标注唯一来源：listMarket 的单次 profile 快照。\n      // 状态不完整且存在可被误标的条目时 fail-closed——不把未知安装状态呈现成未安装；\n      // 空结果（registry 不可用/超时/无匹配）无可误标条目，维持优雅空结果。\n      if (!result.installedComplete && result.items.length > 0) {\n        throw new Error(`读取 ${profile.name} profile 安装状态失败，安装标注不可用；请稍后重试`)\n      }\n      const shown = result.items.length\n      const nextOffset: number | null = offset + shown < result.total ? offset + shown : null\n      return cloneJson({\n        query: String(args.query || ''),\n        category,\n        source,\n        offset,\n        nextOffset,\n        total: result.total,\n        ...(result.publishedAtComplete !== undefined ? { publishedAtComplete: result.publishedAtComplete } : {}),\n        registry: summaryOf(result.registryState),\n        registryNote: registryNoteOf(result.registryState),\n        community: communityToolSummary(result.community),\n        items: result.items.map((e) => ({\n          id: e.id,\n          na